10	pub fn handle(args: CompletionsArgs, _global: &GlobalArgs) -> Result<ExitCode, CliError> {
11	    let mut source = Cli::command();
12	    source.build();
13	    let mut cmd = visible_only(&source);
14	    // Generated into a buffer, then written through the one fallible sink --
15	    // `generate` writing straight to stdout would panic on a closed pipe
16	    // (e.g. `callisto completions bash | head`) instead of exiting quietly.
17	    let mut buf = Vec::new();
18	    generate(args.shell, &mut cmd, "callisto", &mut buf);
19	    write_stdout(&buf)?;
20	    Ok(ExitCode::SUCCESS)
21	}
