23	/// Rebuilds `cmd` without its hidden subcommands, recursively -- `clap_complete`'s
24	/// generators walk `Command::get_subcommands()` unconditionally and do not
25	/// consult `is_hide_set()`, so a plumbing subcommand hidden from `--help`
26	/// would otherwise still be offered in shell completions.
27	fn visible_only(cmd: &Command) -> Command {
28	    // The source command already carries its built-in --help/--version args
29	    // (cloned below via `get_arguments`); without disabling auto-injection,
30	    // clap's `build()` would add a second --help and panic on the duplicate.
31	    let mut out = Command::new(cmd.get_name().to_owned())
32	        .disable_help_flag(true)
33	        .disable_version_flag(true)
34	        .args(cmd.get_arguments().cloned());
35	    if let Some(about) = cmd.get_about() {
36	        out = out.about(about.clone());
37	    }
38	    if let Some(version) = cmd.get_version() {
39	        out = out.version(version.to_owned());
40	    }
41	    let visible_subcommands: Vec<Command> = cmd
42	        .get_subcommands()
43	        .filter(|sub| !sub.is_hide_set())
44	        .map(visible_only)
45	        .collect();
46	    if !visible_subcommands.is_empty() {
47	        out = out.subcommands(visible_subcommands);
48	    }
49	    out
50	}
