fn npm_view_uses_the_publish_config_when_there_is_one() {
    let with_config = npm_view_args("pkg@1.0.0", false, Some("https://registry.example/"), Some("/tmp/npmrc"));
    assert_eq!(
        with_config,
        [
            "view",
            "pkg@1.0.0",
            "--json",
            "--fetch-retries=0",
            "--registry",
            "https://registry.example/",
            "--userconfig",
            "/tmp/npmrc"
        ]
    );
    // Without it the arguments are unchanged: the user's own `.npmrc` and environment variables reach `view` as they are.
