131	/// Classifies one `curl -sS -i` run against the simple index. A private index
132	/// that ignores `Accept` and serves its legacy HTML page fails the JSON parse
133	/// inside `on_ok` and reads as `MalformedResponse`, same as any other body PEP
134	/// 691 JSON parsing cannot make sense of.
135	///
136	/// Any other status shares [`HttpResponse::is_transient`] with GitHub's `gh api` reads, so it retries on
137	/// `Retry-After` instead of settling immediately, and either way reports the status as `ProviderStatus`.
138	pub(super) fn classify_pypi_status<T>(
139	    output: &CommandOutput,
140	    on_ok: impl FnOnce(&str) -> Attempt<T>,
141	    absent: T,
142	    indeterminate: impl Fn(ProviderIndeterminateCause) -> T,
143	) -> Attempt<T> {
144	    let response = match parse_http_response(&output.stdout) {
145	        Ok(response) => response,
146	        Err(_) if !output.success() => {
147	            return Attempt::Transient {
148	                value: indeterminate(ProviderIndeterminateCause::CommandFailed),
149	                retry_after: None,
150	            }
151	        }
152	        Err(_) => {
153	            return Attempt::Transient {
154	                value: indeterminate(ProviderIndeterminateCause::MalformedResponse),
155	                retry_after: None,
156	            }
157	        }
158	    };
159	    match response.status {
160	        200 => on_ok(&response.body),
161	        404 => Attempt::Settled(absent),
162	        status if response.is_transient() => Attempt::Transient {
163	            value: indeterminate(ProviderIndeterminateCause::ProviderStatus { status }),
164	            retry_after: response.retry_after(),
165	        },
166	        status => Attempt::Settled(indeterminate(ProviderIndeterminateCause::ProviderStatus { status })),
167	    }
168	}
