//! The facts a release PR (or any other release-notes surface) renders: what bumps, what changed and what needs a
//! reviewer's attention. Surfaces turn this into text; nothing here knows about Markdown layout.

use std::collections::HashMap;

use callisto_model::{BumpReason, ManifestFormat, PackageId, Severity};
use indexmap::IndexMap;
use serde::Serialize;

use crate::changelog::ChangeSource;
use crate::plan::{PlannedBump, VersionPlan, VersionWriteTarget};

pub const RELEASE_NOTES_SCHEMA_VERSION: u32 = 1;

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ReleaseNotes {
    pub schema_version: u32,
    /// Highest severity first, ties in plan order.
    pub packages: Vec<PackageRelease>,
    /// Highest severity first, ties in first-seen order.
    pub changes: Vec<Change>,
    /// Packages released only because their group moved, with no entry of their own.
    pub bystanders: Vec<String>,
    pub findings: Vec<Finding>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PackageRelease {
    pub name: String,
    pub ecosystem: String,
    pub from: String,
    pub to: String,
    pub severity: Severity,
    pub reason: Option<BumpReason>,
}

/// One underlying change, merged across every package it bumps.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Change {
    pub kind: ChangeKind,
    /// `(package, this entry's own severity)`, not the package's post-cascade severity.
    pub members: Vec<ChangeMember>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ChangeMember {
    pub package: String,
    pub severity: Severity,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum ChangeKind {
    Changeset {
        filename: String,
        summary: String,
    },
    Commit {
        subject: String,
        sha: String,
        short_sha: String,
    },
    PeerEscalation {
        dependency: String,
        to: String,
    },
    DependencyUpdate {
        dependency: String,
        to: String,
    },
    /// A package with no renderable changelog entries, described by why it bumps. Never merged across packages.
    Fallback {
        reason: Option<BumpReason>,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum FindingLevel {
    /// The reviewer should read this before merging.
    Pause,
    Info,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Finding {
    pub id: String,
    pub level: FindingLevel,
    pub message: String,
}

pub fn build_release_notes(plan: &VersionPlan) -> ReleaseNotes {
    let mut sorted: Vec<&PlannedBump> = plan.bumps.iter().collect();
    sorted.sort_by_key(|bump| std::cmp::Reverse(bump.severity));
    let packages = sorted
        .into_iter()
        .map(|bump| PackageRelease {
            name: bump.package.display_name().to_string(),
            ecosystem: ecosystem_label(bump).to_string(),
            from: bump.from.render().to_string(),
            to: bump.to.render().to_string(),
            severity: bump.severity,
            reason: bump.reason.clone(),
        })
        .collect();

    let (changes, bystanders) = collect_changes(plan);

    ReleaseNotes {
        schema_version: RELEASE_NOTES_SCHEMA_VERSION,
        packages,
        changes,
        bystanders,
        findings: assess(&plan.bumps),
    }
}

/// A bare package name carries no ecosystem prefix, so fall back to the manifest it is written to.
fn ecosystem_label(bump: &PlannedBump) -> &'static str {
    if let Some(ecosystem) = bump.package.ecosystem() {
        return ecosystem.prefix();
    }
    bump.writes
        .iter()
        .find_map(|target| match target {
            VersionWriteTarget::CargoWorkspacePackage { .. } => Some("cargo"),
            VersionWriteTarget::Manifest(path) => ManifestFormat::from_path(path)
                .ok()
                .map(|format| format.ecosystem().prefix()),
        })
        .unwrap_or("unknown")
}

/// Identity used to merge one change across every package it bumps. A shared changeset's summary is copied into each
/// package it names, which is right for each package's own changelog and noise in a multi-package PR.
#[derive(Clone, PartialEq, Eq, Hash)]
enum ChangeKey {
    Changeset(String),
    Commit(String),
    PeerEscalation(PackageId, String),
    DependencyUpdate(PackageId, String),
    /// One per package whose changelog section could not render.
    Fallback(usize),
}

fn change_key(source: &ChangeSource) -> Option<ChangeKey> {
    match source {
        ChangeSource::Changeset { filename, .. } => Some(ChangeKey::Changeset(filename.clone())),
        ChangeSource::Commit { sha, .. } => Some(ChangeKey::Commit(sha.as_str().to_string())),
        ChangeSource::PeerEscalation { dependency, to } => {
            Some(ChangeKey::PeerEscalation(dependency.clone(), to.render().to_string()))
        }
        ChangeSource::DependencyUpdate { dependency, to, .. } => {
            Some(ChangeKey::DependencyUpdate(dependency.clone(), to.render().to_string()))
        }
        // Moved because their group did; the package table's reason column already says so.
        ChangeSource::GroupUnion { .. } | ChangeSource::NewGroupMember { .. } => None,
    }
}

/// `None` for a source with nothing to say, matching `render_section`'s own empty-summary skip.
fn change_kind(source: &ChangeSource) -> Option<ChangeKind> {
    match source {
        ChangeSource::Changeset { filename, summary } => {
            if summary.trim().is_empty() {
                return None;
            }
            Some(ChangeKind::Changeset {
                filename: filename.clone(),
                summary: summary.clone(),
            })
        }
        ChangeSource::Commit { subject, sha } => Some(ChangeKind::Commit {
            subject: subject.clone(),
            sha: sha.as_str().to_string(),
            short_sha: sha.short().to_string(),
        }),
        ChangeSource::DependencyUpdate { dependency, to, .. } => Some(ChangeKind::DependencyUpdate {
            dependency: dependency.display_name().to_string(),
            to: to.render().to_string(),
        }),
        ChangeSource::PeerEscalation { dependency, to } => Some(ChangeKind::PeerEscalation {
            dependency: dependency.display_name().to_string(),
            to: to.render().to_string(),
        }),
        ChangeSource::GroupUnion { .. } | ChangeSource::NewGroupMember { .. } => None,
    }
}

fn collect_changes(plan: &VersionPlan) -> (Vec<Change>, Vec<String>) {
    let writes: HashMap<_, _> = plan.changelog_writes.iter().map(|w| (&w.input.package, w)).collect();
    let mut groups: IndexMap<ChangeKey, Change> = IndexMap::new();
    let mut bystanders = Vec::new();
    let mut fallbacks = 0usize;

    for bump in &plan.bumps {
        let write = writes
            .get(&bump.package)
            .copied()
            .filter(|w| crate::changelog::render_section(&w.input).is_ok());

        let Some(write) = write else {
            fallbacks += 1;
            groups.insert(
                ChangeKey::Fallback(fallbacks),
                Change {
                    kind: ChangeKind::Fallback {
                        reason: bump.reason.clone(),
                    },
                    members: vec![ChangeMember {
                        package: bump.package.display_name().to_string(),
                        severity: bump.severity,
                    }],
                },
            );
            continue;
        };

        let mut substantive = false;
        for entry in &write.input.entries {
            let (Some(key), Some(kind)) = (change_key(&entry.source), change_kind(&entry.source)) else {
                continue;
            };
            substantive = true;
            groups
                .entry(key)
                .or_insert_with(|| Change {
                    kind,
                    members: Vec::new(),
                })
                .members
                .push(ChangeMember {
                    package: bump.package.display_name().to_string(),
                    severity: entry.severity,
                });
        }
        if !substantive {
            bystanders.push(bump.package.display_name().to_string());
        }
    }

    let mut changes: Vec<Change> = groups.into_values().collect();
    changes.sort_by_key(|change| std::cmp::Reverse(change.max_severity()));
    (changes, bystanders)
}

impl Change {
    pub fn max_severity(&self) -> Severity {
        self.members
            .iter()
            .map(|member| member.severity)
            .max()
            .unwrap_or(Severity::None)
    }
}

/// What a reviewer should know before merging. Below 1.0.0 a minor bump is where breaking changes go, so it is
/// never called compatible.
pub fn assess(bumps: &[PlannedBump]) -> Vec<Finding> {
    if bumps.iter().any(|bump| bump.severity == Severity::Major) {
        return vec![Finding {
            id: "major-bump".to_owned(),
            level: FindingLevel::Pause,
            message: "This release contains major breaking changes. Review the changes below before merging.".to_owned(),
        }];
    }
    let pre_one_minor = bumps
        .iter()
        .any(|bump| bump.severity == Severity::Minor && bump.from.render().starts_with("0."));
    if pre_one_minor {
        return vec![Finding {
            id: "pre-1.0-minor".to_owned(),
            level: FindingLevel::Pause,
            message: "Minor bumps below 1.0.0 can include breaking changes, so read the changes below before merging."
                .to_owned(),
        }];
    }
    vec![Finding {
        id: "compatible".to_owned(),
        level: FindingLevel::Info,
        message: "All changes are backward compatible.".to_owned(),
    }]
}

use callisto_model::{BumpReason, CommandRunner, ComposePrBodyReport, Severity, SCHEMA_VERSION};

use crate::changelog::render::indent_changeset_summary;
use crate::commands::version::plan_version;
use crate::error::GraphError;
use crate::infer::SeverityInference;
use crate::release_notes::{
    assess, build_release_notes, Change, ChangeKind, Finding, ReleaseNotes, FINDING_MAJOR_BUMP,
};
use crate::resolver::DependencyResolver;
use crate::Workspace;

#[derive(Clone, Debug, Default)]
pub struct PrBodyOptions {
    pub existing_body: Option<String>,
    pub branch: Option<String>,
}

fn severity_emoji(severity: Severity) -> &'static str {
    match severity {
        Severity::Major => "🔴",
        Severity::Minor => "🟡",
        Severity::Patch => "🟢",
        Severity::None => "⚪",
    }
}

/// One change's bullet text. `None` for a change with nothing to say.
fn entry_text(kind: &ChangeKind) -> Option<String> {
    match kind {
        ChangeKind::Changeset { summary, .. } => indent_changeset_summary(summary),
        ChangeKind::Commit { subject, short_sha, .. } => Some(format!("{subject} ({short_sha})")),
        ChangeKind::DependencyUpdate { dependency, to } => Some(format!("`{dependency}` → `{to}`")),
        ChangeKind::PeerEscalation { dependency, to } => {
            Some(format!("Peer dependency `{dependency}` requires `{to}`"))
        }
        ChangeKind::Fallback { reason } => Some(fallback_reason_text(reason)),
    }
}

/// A short, stable label for a change's `<summary>`, from its identity and never from its free-text body.
fn change_label(kind: &ChangeKind) -> String {
    match kind {
        ChangeKind::Changeset { filename, .. } => {
            format!("`{}`", filename.strip_suffix(".md").unwrap_or(filename))
        }
        ChangeKind::Commit { sha, .. } => format!("Commit `{}`", &sha[..sha.len().min(7)]),
        ChangeKind::PeerEscalation { dependency, to } => format!("Peer dependency `{dependency}` → `{to}`"),
        ChangeKind::DependencyUpdate { dependency, to } => format!("Dependency `{dependency}` → `{to}`"),
        ChangeKind::Fallback { .. } => unreachable!("Fallback changes render via their sole member, not this label"),
    }
}

/// Text for a package with no renderable changelog entries, from why it bumps.
fn fallback_reason_text(reason: &Option<BumpReason>) -> String {
    match reason {
        Some(reason) => match reason {
            BumpReason::Changeset { changesets } => {
                format!("- Associated changesets: `{}`\n", changesets.join("`, `"))
            }
            BumpReason::Cascade {
                via,
                spec,
                dependency_to,
                ..
            } => {
                format!(
                    "- Automatic dependency cascade triggered by `{}` (spec `{}` target `{}`).\n",
                    via.display_name(),
                    spec,
                    dependency_to.render()
                )
            }
            BumpReason::PeerEscalation { via, spec } => {
                format!(
                    "- Peer dependency escalation triggered by `{}` (spec `{}`).\n",
                    via.display_name(),
                    spec
                )
            }
            BumpReason::FixedGroupUnion { group } => {
                format!("- Fixed group synchronization for group `{}`.\n", group.as_str())
            }
            BumpReason::LinkedGroupUnion { group } => {
                format!("- Linked group version alignment for group `{}`.\n", group.as_str())
            }
            BumpReason::Inference { commits, .. } => {
                format!("- Inferred from {commits} commit(s) since the last release.\n")
            }
            BumpReason::PreRelease { tag } => {
                format!("- Pre-release finalization (tag `{tag}`).\n")
            }
            BumpReason::NewGroupMember { group } => {
                format!("- New member of group `{}`.\n", group.as_str())
            }
            _ => "_No changelog entries available._\n".to_string(),
        },
        None => "_No changelog entries available._\n".to_string(),
    }
}

fn reason_cell(reason: &Option<BumpReason>) -> String {
    match reason {
        Some(BumpReason::Changeset { changesets }) => {
            format!("Changeset (`{}`)", changesets.join("`, `"))
        }
        Some(BumpReason::Cascade { via, .. }) => {
            format!("Cascade from `{}`", via.display_name())
        }
        Some(BumpReason::PeerEscalation { via, .. }) => {
            format!("Peer escalation from `{}`", via.display_name())
        }
        Some(BumpReason::FixedGroupUnion { group }) => {
            format!("Fixed group `{}`", group.as_str())
        }
        Some(BumpReason::LinkedGroupUnion { group }) => {
            format!("Linked group `{}`", group.as_str())
        }
        Some(BumpReason::Inference { commits, .. }) => {
            format!("Inferred ({commits} commits)")
        }
        Some(BumpReason::PreRelease { tag }) => {
            format!("Prerelease (`{tag}`)")
        }
        Some(BumpReason::NewGroupMember { group }) => {
            format!("New member (`{}`)", group.as_str())
        }
        _ => "Package bump".to_string(),
    }
}

pub fn compose_pr_body<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
    ws: &Workspace<'_, R, D>,
    inference: &I,
    opts: &PrBodyOptions,
) -> Result<ComposePrBodyReport, GraphError> {
    let plan = plan_version(ws, inference, &crate::commands::version::VersionOptions::default())?;
    render_pr_body_from_plan(&plan, opts)
}

pub fn render_pr_body_from_plan(
    plan: &crate::plan::VersionPlan,
    opts: &PrBodyOptions,
) -> Result<ComposePrBodyReport, GraphError> {
    Ok(ComposePrBodyReport {
        schema_version: SCHEMA_VERSION,
        body: render_pr_body(&build_release_notes(plan), opts),
        diagnostics: Vec::new(),
    })
}

fn workflow_instructions(branch: &str) -> String {
    let mut out = String::new();
    out.push_str("<details>\n<summary><b>Release Workflow Instructions</b></summary>\n\n");
    out.push_str("- **Merging this PR**: Merging into `main` will automatically publish all updated packages to their release registries.\n");
    out.push_str("- **Adding more changesets**: If additional changesets are pushed to `main`, Callisto will automatically re-calculate and update this PR.\n");
    out.push_str(&format!(
        "- **Manual edits**: You can make manual adjustments directly on the `{branch}` branch if needed.\n\n"
    ));
    out.push_str("</details>\n");
    out
}

fn render_pr_body(notes: &ReleaseNotes, opts: &PrBodyOptions) -> String {
    let mut body = String::new();

    // Preserve custom user notes above ## Release Preview if an existing body was passed
    if let Some(ref existing) = opts.existing_body
        && let Some((prefix, _)) = existing.split_once("## Release Preview")
        && !prefix.trim().is_empty()
    {
        body.push_str(prefix);
        if !prefix.ends_with('\n') {
            body.push('\n');
        }
    }

    body.push_str("## Release Preview\n\n");
    body.push_str("This automated PR was generated by [Callisto](https://github.com/orin-dx/callisto). Merging this PR will publish the updated packages to their release targets.\n\n");

    let branch = opts.branch.as_deref().unwrap_or("callisto/version-packages");

    if notes.packages.is_empty() {
        body.push_str("> [!NOTE]\n");
        body.push_str("> **No pending changesets found.** Workspace packages are currently up to date.\n\n");
        body.push_str(&workflow_instructions(branch));
        return body;
    }

    // Major-first (the order `notes.packages` already has): a reviewer's real question is "is anything breaking,"
    // and that must be answerable from the top of the table without scanning every row.
    body.push_str("### 📊 Release Summary\n\n");
    body.push_str("| Package | Ecosystem | Current | Target | Bump | Reason |\n");
    body.push_str("| :--- | :--- | :--- | :--- | :--- | :--- |\n");
    for package in &notes.packages {
        body.push_str(&format!(
            "| `{}` | `{}` | `{}` | **`{}`** | {} `{}` | {} |\n",
            package.name,
            package.ecosystem,
            package.from,
            package.to,
            severity_emoji(package.severity),
            package.severity,
            reason_cell(&package.reason)
        ));
    }
    body.push('\n');

    body.push_str(&callout(&notes.findings, notes.packages.len()));

    // Grouped by underlying change, not by package, so a changeset naming several packages renders once.
    body.push_str("### 📦 What's Changing\n\n");

    if !notes.bystanders.is_empty() {
        let names: Vec<String> = notes.bystanders.iter().map(|name| format!("`{name}`")).collect();
        body.push_str(&format!(
            "_Also bumped with no direct change of their own (released together via a fixed/linked group): {}._\n\n",
            names.join(", ")
        ));
    }

    body.push_str(&format!(
        "**{} change(s) across {} package(s):**\n\n",
        notes.changes.len(),
        notes.packages.len()
    ));

    for change in &notes.changes {
        render_change(&mut body, change);
    }

    body.push_str(&workflow_instructions(branch));
    body
}

fn render_change(body: &mut String, change: &Change) {
    let open = if change.max_severity() == Severity::Major {
        " open"
    } else {
        ""
    };

    if let ChangeKind::Fallback { .. } = change.kind {
        let member = &change.members[0];
        body.push_str(&format!(
            "<details{open}>\n<summary><b>{}</b> ({} {})</summary>\n\n",
            member.package,
            severity_emoji(member.severity),
            member.severity
        ));
    } else {
        let affected: Vec<String> = change
            .members
            .iter()
            .map(|member| format!("<code>{}</code>", member.package))
            .collect();
        body.push_str(&format!(
            "<details{open}>\n<summary><b>{}</b> — affects {}</summary>\n\n",
            change_label(&change.kind),
            affected.join(", ")
        ));
    }

    let text = entry_text(&change.kind).unwrap_or_default();
    body.push_str(&text);
    if !text.ends_with('\n') {
        body.push('\n');
    }
    body.push_str("\n</details>\n\n");
}

/// The callout that opens the release PR body.
fn callout(findings: &[Finding], package_count: usize) -> String {
    if let Some(major) = findings.iter().find(|finding| finding.id == FINDING_MAJOR_BUMP) {
        return format!(
            "> [!WARNING]\n> **Major Version Bumps Detected**: {}\n\n",
            major.message
        );
    }
    let verdict = findings.first().map(|finding| finding.message.as_str()).unwrap_or_default();
    format!("> [!NOTE]\n> **{package_count} package(s)** queued for versioning. {verdict}\n\n")
}

