import re, pathlib

root = pathlib.Path("/Users/gabe/Projects/callisto/crates")
hits = []
for path in root.rglob("*.rs"):
    if "/tests/" in str(path) or "target" in path.parts:
        continue
    text = path.read_text()
    lines = text.split("\n")
    for i, line in enumerate(lines):
        m = re.match(r"\s*pub(?:\(crate\))? enum (\w+)", line) or re.match(r"\s*enum (\w+)", line)
        if not m:
            continue
        # gather attributes above
        j = i - 1
        attrs = []
        while j >= 0 and (lines[j].strip().startswith("#[") or lines[j].strip().startswith("///") or lines[j].strip() == ""):
            attrs.append(lines[j])
            j -= 1
        attr = "\n".join(attrs)
        if "Serialize" not in attr and "Deserialize" not in attr:
            continue
        if "rename_all_fields" in attr:
            continue
        # find enum body by brace matching
        depth = 0
        body = []
        for k in range(i, len(lines)):
            depth += lines[k].count("{") - lines[k].count("}")
            body.append(lines[k])
            if depth == 0 and k > i:
                break
        # struct variants: lines like `Name {` then fields until `}`
        in_variant = False
        for b in body[1:]:
            s = b.strip()
            if re.match(r"^[A-Z]\w*\s*\{\s*$", s) or re.match(r"^[A-Z]\w*\s*\{.*[a-z_]+:\s*", s):
                in_variant = True
            fm = re.findall(r"\b([a-z]+_[a-z_]+)\s*:", s)
            if in_variant and fm and "rename" not in s:
                for f in fm:
                    hits.append((str(path.relative_to(root.parent)), i + 1, m.group(1), f, "camelCase" in attr))
            if s.startswith("}") or s.endswith("},"):
                in_variant = False
for h in sorted(set(hits)):
    print(h)

